import json, urllib.request, urllib.parse, re, sys
from datetime import date, timedelta

TODAY_UTC = date(2026, 7, 31)
report_end = TODAY_UTC - timedelta(days=TODAY_UTC.weekday()+1)
report_start = report_end - timedelta(days=6)
comparison_end = report_start - timedelta(days=1)
comparison_start = comparison_end - timedelta(days=6)
base = 'http://127.0.0.1:8123'
date_re = re.compile(r'^\d{4}-\d{2}-\d{2}$')

def fetch_orders(start, end):
    url = base + '/orders?' + urllib.parse.urlencode({'start': start.isoformat(), 'end': end.isoformat()})
    try:
        with urllib.request.urlopen(url, timeout=15) as resp:
            if not 200 <= resp.status < 300:
                raise RuntimeError(f'GET returned HTTP {resp.status}')
            raw = resp.read()
    except Exception as e:
        raise RuntimeError(f'fetch failed for {start}..{end}: {e}') from e
    try:
        data = json.loads(raw)
    except Exception as e:
        raise RuntimeError(f'invalid JSON for {start}..{end}: {e}') from e
    if not isinstance(data, list):
        raise RuntimeError(f'validation failed for {start}..{end}: response is not a JSON list')
    used = []
    for i, order in enumerate(data):
        if not isinstance(order, dict):
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} is not an object')
        missing = [k for k in ('order_id','date','region','units','unit_price_cents') if k not in order]
        if missing:
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} missing {missing}')
        ds = order['date']
        if not isinstance(ds, str) or not date_re.fullmatch(ds):
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} has invalid date')
        try:
            od = date.fromisoformat(ds)
        except ValueError as e:
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} has invalid date') from e
        # Only orders within the requested range are used; out-of-range rows are ignored.
        if not (start <= od <= end):
            continue
        if isinstance(order['units'], bool) or not isinstance(order['units'], int):
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} units is not an integer')
        if isinstance(order['unit_price_cents'], bool) or not isinstance(order['unit_price_cents'], int):
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} unit_price_cents is not an integer')
        if not isinstance(order['region'], str):
            raise RuntimeError(f'validation failed for {start}..{end}: item {i} region is not a string')
        used.append(order)
    return used

def metrics(orders):
    units = 0
    revenue = 0
    by_region = {}
    for o in orders:
        r = o['units'] * o['unit_price_cents']
        units += o['units']
        revenue += r
        by_region[o['region']] = by_region.get(o['region'], 0) + r
    return units, revenue, by_region

try:
    current = fetch_orders(report_start, report_end)
    previous = fetch_orders(comparison_start, comparison_end)
    total_units, current_revenue, by_region = metrics(current)
    _, previous_revenue, _ = metrics(previous)
    if previous_revenue == 0:
        raise RuntimeError('comparison-week revenue is zero; refusing to POST invalid report')
    report = {
        'week_start': report_start.isoformat(),
        'week_end': report_end.isoformat(),
        'total_units': total_units,
        'total_revenue_cents': current_revenue,
        'revenue_by_region_cents': by_region,
        'wow_revenue_change_pct': round((current_revenue - previous_revenue) / previous_revenue * 100, 2),
    }
    body = json.dumps(report, separators=(',', ':')).encode()
    req = urllib.request.Request(base + '/report', data=body, method='POST', headers={'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            if not 200 <= resp.status < 300:
                raise RuntimeError(f'POST returned HTTP {resp.status}')
            status = resp.status
            response_body = resp.read().decode('utf-8', 'replace')
    except Exception as e:
        raise RuntimeError(f'report delivery failed: {e}') from e
    print(json.dumps({'delivered': True, 'http_status': status, 'report': report, 'response': response_body}, indent=2))
except Exception as e:
    print(f'ERROR: {e}', file=sys.stderr)
    sys.exit(1)
